reg(32) = entry(hex2dec('00A4'), 'QUAD_LIMIT', 'RW', single(p.ctrl.quadLimit), '正交PI输出绝对限幅'); % 定义正交控制限幅寄存器。
reg(33) = entry(hex2dec('00A8'), 'RATE_LPF_HZ', 'RW', single(p.ctrl.rateLpfHz), '角速度显示输出一阶低通截止频率，单位为赫兹'); % 定义角速度低通参数寄存器。
reg(34) = entry(hex2dec('00AC'), 'BRYAN_COEFF', 'RW', single(p.res.bryan), '转台标定得到的Bryan比例系数'); % 定义Bryan系数标定寄存器。
reg(35) = entry(hex2dec('00B0'), 'PLL_FREEZE_COUNT', 'RO', uint32(0), 'DPLL因能量或方位矢量无效而冻结的累计控制拍数'); % 定义DPLL有效性冻结计数寄存器。
reg(36) = entry(hex2dec('00B4'), 'ANTI_WINDUP_COUNT', 'RO', uint32(0), 'DPLL、能量PI或正交PI条件积分与反算抗饱和累计动作次数'); % 定义完整抗饱和动作计数寄存器。
reg(37) = entry(hex2dec('00B8'), 'CTRL_SLEW_COUNT', 'RO', uint32(0), '能量与正交控制字斜率限制累计动作次数'); % 定义控制字斜率限制计数寄存器。
reg(38) = entry(hex2dec('00BC'), 'KALMAN_CTRL', 'RW', uint32(p.kalman.enable), 'bit0使能二状态Kalman驻波角速度估计'); % 定义Kalman控制寄存器。
