reg(41) = entry(hex2dec('00C8'), 'KALMAN_REJECT_COUNT', 'RO', uint32(0), 'Kalman创新超限拒绝累计次数'); % 定义Kalman创新拒绝计数寄存器。
reg(42) = entry(hex2dec('00D0'), 'SELFTEST_CTRL', 'RW', uint32(p.selftest.enable), 'bit0自动使能，bit1软件触发，bit2通过后返回RUN'); % 定义SELFTEST控制寄存器。
