reg(46) = entry(hex2dec('00E0'), 'SELFTEST_STATUS', 'RO', uint32(0), 'bit0活动，bit1完成，bit2通过，bit3失败'); % 定义SELFTEST独立状态寄存器。
reg(47) = entry(hex2dec('00E4'), 'MEAS_INVALID_REASON', 'RO', uint32(0), 'bit0低能量，bit1低方位矢量，bit2 AFE或ADC饱和，bit3定点溢出，bit4非有限数'); % 定义本拍测量无效原因位图寄存器。
reg(48) = entry(hex2dec('00E8'), 'ACTUATOR_TRACK_COUNT', 'RO', uint32(0), '执行器物理饱和与控制字斜率限制跟踪反算累计次数'); % 定义后级执行约束跟踪反算计数寄存器。
reg(49) = entry(hex2dec('00EC'), 'NOISE_ANALYSIS_CTRL', 'RW', uint32(p.analysis.autoRun), 'bit0允许仿真后自动执行Allan与PSD分析'); % 定义噪声可信度分析控制寄存器。
reg(50) = entry(hex2dec('00F0'), 'MODEL_REVISION', 'RO', uint32(hex2dec('00040500')), '行为模型版本编码，当前为V4.5'); % 定义模型修订版本寄存器。
reg(51) = entry(hex2dec('0100'), 'CALIB_CTRL', 'RW', uint32(p.calib.enable), 'bit0在线标定使能，bit1正弦自激，bit2检测矩阵校正，bit3驱动矩阵预补偿，bit4 RLS，bit5 EKF'); % 定义在线标定控制寄存器。
reg(52) = entry(hex2dec('0104'), 'CALIB_START_TIME', 'RW', single(p.calib.startTime), '在线标定允许启动时刻，单位为秒'); % 定义在线标定启动时刻寄存器。
reg(53) = entry(hex2dec('0108'), 'CALIB_EXCITE_AMP', 'RW', single(p.calib.excitationAmplitude), '在线正弦自激幅值'); % 定义在线标定自激幅值寄存器。
reg(54) = entry(hex2dec('010C'), 'CALIB_EXCITE_HZ', 'RW', single(p.calib.excitationFrequencyHz), '在线正弦自激同步解调频率，单位为赫兹'); % 定义在线标定自激频率寄存器。
reg(55) = entry(hex2dec('0110'), 'CALIB_RLS_LAMBDA', 'RW', single(p.calib.rlsLambda), '检测/驱动矩阵RLS遗忘因子'); % 定义RLS遗忘因子寄存器。
reg(56) = entry(hex2dec('0114'), 'CALIB_UPDATE_COUNT', 'RO', uint32(0), '在线RLS/EKF参数更新次数'); % 定义在线标定更新计数寄存器。
reg(57) = entry(hex2dec('0118'), 'CALIB_DET_MATRIX0', 'RO', uint32(0), '检测矩阵估计m11/m12打包或相邻影子寄存器起始地址'); % 定义检测矩阵估计寄存器。
reg(58) = entry(hex2dec('011C'), 'CALIB_DRV_MATRIX0', 'RO', uint32(0), '驱动矩阵估计d11/d12打包或相邻影子寄存器起始地址'); % 定义驱动矩阵估计寄存器。
reg(59) = entry(hex2dec('0120'), 'CALIB_DAMPING', 'RO', single(0), '在线阻尼不均匀幅值估计'); % 定义阻尼不均匀估计寄存器。
reg(60) = entry(hex2dec('0124'), 'CALIB_SPLIT_HZ', 'RO', single(0), '在线模态频率裂解估计，单位为赫兹'); % 定义模态裂解估计寄存器。
